import React from 'react';

const Header = ({ onOpenSettings, currentLang }) => {
  return (
    <header className="w-full p-6 flex justify-between items-center bg-[#0D0D0D] border-b border-[#F2F2F2]/10 z-50">
      <div className="font-archivo text-2xl tracking-tighter text-[#F2F2F2] cursor-pointer" onClick={() => window.location.reload()}>
        RAW<span className="text-raw-cyan">.</span>
      </div>
      
      <div className="flex items-center space-x-6">
        <div className="text-[9px] font-archivo text-raw-bone/30 uppercase tracking-[0.2em] border border-raw-bone/10 px-2 py-1">
          REGION: {currentLang}
        </div>
        <button 
          onClick={onOpenSettings}
          className="group flex items-center space-x-2"
        >
          <div className="w-2 h-2 bg-raw-cyan rounded-full group-hover:animate-ping"></div>
          <span className="text-[10px] text-raw-bone/60 uppercase tracking-widest font-bold">Menu</span>
        </button>
      </div>
    </header>
  );
};

export default Header;
